enum Status {
    Success(u32),
    Redirect { code: u32, url: String },
    Error(String),
}

fn handle_status(status: Status) {
    match status {
        // 가드절과 페이로드 분해
        Status::Success(code) if code == 200 => println!("200 OK 정상 처리"),
        Status::Success(code) => println!("기타 성공 코드: {code}"),
        // 구조체 패턴 분해
        Status::Redirect { code, url } => println!("리다이렉트 ({code}) -> {url}"),
        // @ 서브패턴 바인딩
        Status::Error(msg @ ref m) if m.contains("critical") => {
            println!("치명적 오류 발생: {msg}");
        }
        Status::Error(msg) => println!("일반 오류: {msg}"),
    }
}

fn process_id(id_opt: Option<u64>) {
    // let-else: 패턴 매치 실패 시 반드시 반환/패닉(diverge) 강제
    let Some(id) = id_opt else {
        println!("유효하지 않은 ID, 조기 종료");
        return;
    };
    println!("처리된 ID: {id}");
}

