use std::collections::{HashMap, HashSet};

fn main() {
    let text = "rust go rust python rust go c";
    let mut word_counts = HashMap::new();

    // Entry API를 활용한 우아한 카운팅 (불필요한 조회 중복 제거)
    for word in text.split_whitespace() {
        let count = word_counts.entry(word).or_insert(0);
        *count += 1;
    }
    println!("단어 빈도수: {:?}", word_counts);

    // HashSet을 통한 고유 집합 및 교집합/합집합 연산
    let set_a: HashSet<&str> = ["apple", "banana", "cherry"].into_iter().collect();
    let set_b: HashSet<&str> = ["banana", "date", "fig"].into_iter().collect();

    let common: HashSet<_> = set_a.intersection(&set_b).cloned().collect();
    println!("공통 과일: {:?}", common);
}

