fn main() {
    let shared_data = Arc::new(vec![1, 2, 3, 4, 5]);

    let mut handles = vec![];

    for i in 0..3 {
        let data_ref = Arc::clone(&shared_data); // 참조 카운트 원자적 증가
        let handle = thread::spawn(move || {
            println!("스레드 {i}: 첫 번째 요소 = {}, 공유 카운트 = {}", data_ref[0], Arc::strong_count(&data_ref));
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }
    println!("모든 스레드 종료 후 메인 카운트: {}", Arc::strong_count(&shared_data));
}

