use std::sync::mpsc;
use std::thread;
use std::time::Duration;

fn main() {
    // 비동기 무제한 버퍼 채널 생성
    let (tx, rx) = mpsc::channel();

    // 여러 프로듀서 스레드 생성 (tx를 복제하여 다중 송신자 구성)
    for id in 1..=2 {
        let thread_tx = tx.clone();
        thread::spawn(move || {
            let messages = vec![format!("스레드 {id} 메시지 A"), format!("스레드 {id} 메시지 B")];
            for msg in messages {
                thread_tx.send(msg).unwrap(); // 소유권 전송
                thread::sleep(Duration::from_millis(50));
            }
        });
    }
    drop(tx); // 메인 스레드의 원본 tx를 드롭해야 rx 루프가 정상 종료됨

    // 단일 수신자가 메시지 소진
    for received in rx {
        println!("수신 완료: {received}");
    }
}

