use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

fn main() {
    let lock_counter = Arc::new(Mutex::new(0));
    let atomic_counter = Arc::new(AtomicUsize::new(0));

    let mut handles = vec![];

    for _ in 0..10 {
        let lock_clone = Arc::clone(&lock_counter);
        let atomic_clone = Arc::clone(&atomic_counter);

        let handle = thread::spawn(move || {
            // Mutex 락 획득 (스코프 벗어날 때 Guard가 RAII로 자동 해제)
            {
                let mut guard = lock_clone.lock().unwrap();
                *guard += 1;
            }
            // 원자적 연산: 락 없이 하드웨어 명령어로 즉시 증가
            atomic_clone.fetch_add(1, Ordering::Relaxed);
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    println!("Mutex 카운터: {}", *lock_counter.lock().unwrap());
    println!("Atomic 카운터: {}", atomic_counter.load(Ordering::SeqCst));
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};

// 수동 Future 구현 예시 (상태 머신 원리)
struct SimpleTimer {
    completed: bool,
}

impl Future for SimpleTimer {
    type Output = &'static str;

    fn poll(mut self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Self::Output> {
        if self.completed {
            Poll::Ready("타이머 작업 완료!")
        } else {
            self.completed = true;
            Poll::Pending // 아직 미완료 상태 -> 실행기에 양보
        }
    }
}

async fn async_workflow() -> String {
    let timer = SimpleTimer { completed: false };
    let status = timer.await; // .await를 통한 지연 평가 및 완료 대기
    format!("결과: {status}")
}

